#include <cstdlib>
#include <algorithm>

class Solution {
public:
    int minMovesToCaptureTheQueen(int a, int b, int c, int d, int e, int f) {
        if (a == e) {
            if (!(c == a && d > std::min(b, f) && d < std::max(b, f))) {
                return 1;
            }
        }
        if (b == f) {
            if (!(d == b && c > std::min(a, e) && c < std::max(a, e))) {
                return 1;
            }
        }
        if (std::abs(c - e) == std::abs(d - f)) {
            bool rookBlocks = (std::abs(c - a) == std::abs(d - b)) &&
                              (std::abs(e - a) == std::abs(f - b)) &&
                              (a > std::min(c, e) && a < std::max(c, e)) &&
                              (b > std::min(d, f) && b < std::max(d, f));
            if (!rookBlocks) {
                return 1;
            }
        }
        return 2;
    }
};

